# ═══════════════════════════════════════════════════════════════════════════════════

print("Splitting Dataset 1 by geography...")

# Separate Pakistan from rest of world
df1_pakistan = df1_raw[df1_raw['Country'] == 'Pakistan'].copy()
df1_global = df1_raw[df1_raw['Country'] != 'Pakistan'].copy()

print(f"✓ Dataset 1 Split:")
