print("█ SECTION 2: FEATURE ENGINEERING (DATASET 2 REMOVED, 80/20 SPLIT ADDED)")
print("█"*90 + "\n")

from sklearn.impute import SimpleImputer

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 1: Define 25 pre-diagnostic features
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 1: Defining 25 pre-diagnostic features...")

PRE_DIAGNOSTIC_FEATURES = {
    'Demographics': ['Age', 'Gender'],
    'Risk_Factors': [
        'Smoking_History', 'Alcohol_Consumption', 'Obesity_BMI',
        'Diabetes', 'Inflammatory_Bowel_Disease', 'Family_History',
        'Diet_Risk', 'Physical_Activity'
    ],
    'Symptoms': [
        'Abdominal Pain', 'Bleeding PR', 'Weight Loss', 'Bowel Change',
        'Tenesmus', 'Anemia related symptoms'
    ],
    'Physical_Exam': [
        'Abdominal Mass Palpable', 'PR Exam Suspicious',
        'Pallor'
    ],
    'Lab_Tests': [
        'Hemoglobin ', 'FIT/FOBT', 'CEA_Level',
        'Liver function Test', 'serum Albumin'
    ]
}

FLAT_FEATURES = []
for category, features in PRE_DIAGNOSTIC_FEATURES.items():
    FLAT_FEATURES.extend(features)

print(f"✓ Pre-diagnostic features defined: {len(FLAT_FEATURES)} total\n")

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 2: Get available features from Dataset 1
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 2: Checking available features...")

features_d1 = [f for f in FLAT_FEATURES if f in df1_global.columns]

print(f"✓ Features available in Dataset 1: {len(features_d1)}\n")

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 3: Create target variable and initial datasets
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 3: Creating datasets and target variable...")

# Global dataset (will be split 80/20)
df1_global_features = df1_global[features_d1].copy()
y_global = df1_global['Cancer_Stage'].apply(
    lambda x: 1 if x in ['Regional', 'Distant'] else 0
).copy()

# Pakistan dataset (for geographic validation - no split)
df1_pakistan_features = df1_pakistan[features_d1].copy()
y_pakistan = df1_pakistan['Cancer_Stage'].apply(
    lambda x: 1 if x in ['Regional', 'Distant'] else 0
).copy()

print(f"Global data shape: {df1_global_features.shape}")
print(f"Pakistan data shape: {df1_pakistan_features.shape}\n")

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 4: 80/20 split on Global data (TRAINING and INTERNAL TEST)
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 4: 80/20 stratified split on Global data...")

X_train_global, X_test_global, y_train_global, y_test_global = train_test_split(
    df1_global_features,
    y_global,
    test_size=0.2,
    stratify=y_global,
    random_state=RANDOM_SEED
)

print(f"✓ Training set: {X_train_global.shape[0]:,} samples ({X_train_global.shape[0]/len(y_global)*100:.1f}%)")
print(f"✓ Internal test set: {X_test_global.shape[0]:,} samples ({X_test_global.shape[0]/len(y_global)*100:.1f}%)")
print(f"✓ Pakistan hold-out: {len(y_pakistan):,} samples\n")

# Rename for compatibility with rest of pipeline
df1_training = X_train_global.copy()
y_training = y_train_global.copy()

df1_test = X_test_global.copy()
y_test = y_test_global.copy()

df1_pakistan_test = df1_pakistan_features.copy()
y_pakistan_test = y_pakistan.copy()

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 5: Encode categorical variables
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 5: Encoding categorical variables...")

# Find categorical columns
categorical_cols = df1_training.select_dtypes(include=['object']).columns.tolist()
le_dict = {}

for col in categorical_cols:
    le = LabelEncoder()

    # Fit on training data
    df1_training[col] = le.fit_transform(df1_training[col].astype(str))

    # Transform test data using training encoder
    if col in df1_test.columns:
        df1_test[col] = le.transform(df1_test[col].astype(str))

    # Transform Pakistan data using training encoder
    if col in df1_pakistan_test.columns:
        try:
            df1_pakistan_test[col] = le.transform(df1_pakistan_test[col].astype(str))
        except:
            # If unseen category, map to first class
            df1_pakistan_test[col] = 0

    le_dict[col] = le

print(f"✓ Encoded {len(le_dict)} categorical variables\n")

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 6: Impute missing values
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 6: Imputing missing values...")

# Fit imputer on training data only (no data leakage)
imputer = SimpleImputer(strategy='median')

df1_training = pd.DataFrame(
    imputer.fit_transform(df1_training),
    columns=features_d1
)

# Transform test and Pakistan data
df1_test = pd.DataFrame(
    imputer.transform(df1_test),
    columns=features_d1
)

df1_pakistan_test = pd.DataFrame(
    imputer.transform(df1_pakistan_test),
    columns=features_d1
)

print(f"✓ Missing values imputed (using median strategy)\n")

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 7: Scale features (StandardScaler)
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 7: Scaling features (StandardScaler)...")

scaler = StandardScaler()

# Fit on training data
X_training_scaled = scaler.fit_transform(df1_training)

# Transform test and Pakistan using training scaler
X_test_scaled = scaler.transform(df1_test)
X_pakistan_test_scaled = scaler.transform(df1_pakistan_test)

print(f"✓ Features scaled using StandardScaler")
print(f"  Training shape: {X_training_scaled.shape}")
print(f"  Internal test shape: {X_test_scaled.shape}")
print(f"  Pakistan test shape: {X_pakistan_test_scaled.shape}\n")

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 8: Verification & Summary
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 8: Final Verification")
print("="*90)

print(f"""
DATASETS READY:

  Training Set:
    - Shape: {X_training_scaled.shape}
    - Target: {y_training.shape}
    - Cancer cases: {int(y_training.sum()):,} ({y_training.sum()/len(y_training)*100:.2f}%)

  Internal Test Set:
    - Shape: {X_test_scaled.shape}
    - Target: {y_test.shape}
    - Cancer cases: {int(y_test.sum()):,} ({y_test.sum()/len(y_test)*100:.2f}%)

  Pakistan Hold-Out (Geographic Validation):
    - Shape: {X_pakistan_test_scaled.shape}
    - Target: {y_pakistan_test.shape}
    - Cancer cases: {int(y_pakistan_test.sum()):,} ({y_pakistan_test.sum()/len(y_pakistan_test)*100:.2f}%)

FEATURES:
  - Total: {len(features_d1)}
  - All numeric (scaled)
  - No NaN values
  - Stratified split on training/test

""")

