import numpy as np
from sklearn.tree import DecisionTreeClassifier
from sklearn.metrics import roc_auc_score, recall_score, precision_score, f1_score

print("Training Decision Tree...\n")

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 1: Train Decision Tree on TRAINING data
# ═══════════════════════════════════════════════════════════════════════════════════

print("="*90)
print("STEP 1: Training Decision Tree")
print("="*90 + "\n")

tree_model = DecisionTreeClassifier(
    max_depth=3,
    random_state=RANDOM_SEED,
    min_samples_split=50
)

print("Fitting tree on training data...")
tree_model.fit(X_training_scaled, y_training)
print(f"  ✓ Tree trained. Depth: {tree_model.get_depth()}\n")

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 2: GET FEATURE IMPORTANCES (Data-Driven - NOT Hardcoded!)
# ═══════════════════════════════════════════════════════════════════════════════════

print("="*90)
print("STEP 2: Calculating Feature Importances from Tree")
print("="*90 + "\n")

print("✓ Tree feature_importances_ calculated")

# Get feature importances from tree
feature_importances = tree_model.feature_importances_

print(f"  Total features: {len(feature_importances)}")
print(f"  Non-zero importances: {(feature_importances > 0).sum()}\n")

# Get indices sorted by importance (descending)
sorted_indices = np.argsort(feature_importances)[::-1]

print("Top 10 features (by tree importance):\n")
print(f"  Rank | Feature Name                    | Importance")
print(f"  ─────┼────────────────────────────────┼─────────────")

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 3: SELECT TOP 10 FEATURES (Data-Driven - From Actual Importances!)
# ═══════════════════════════════════════════════════════════════════════════════════

top_10_indices = sorted_indices[:15]  # Get top 10 indices
top_10_features = [features_d1[i] for i in top_10_indices]  # Get feature names
top_10_importances = feature_importances[top_10_indices]  # Get importance values

for rank, (idx, feat, imp) in enumerate(zip(range(1, 16), top_10_features, top_10_importances), 1):
    print(f"  {rank:2d}   | {top_10_features[rank-1]:30s} | {top_10_importances[rank-1]:.6f}")

print()

# Verify all features found
print(f"✓ Successfully selected top 10 features from ACTUAL tree importance")
print(f"✓ Features list (data-driven):")
for i, feat in enumerate(top_10_features, 1):
    print(f"    {i:2d}. {feat}")

print()

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 4: CREATE TOP 10 TRAINING DATA
# ═══════════════════════════════════════════════════════════════════════════════════

print("="*90)
print("STEP 3: Creating Top 10 Training Dataset")
print("="*90 + "\n")

X_training_scaled_top10 = X_training_scaled[:, top_10_indices]

print(f"Original training data shape: {X_training_scaled.shape}")
print(f"Top 10 training data shape:   {X_training_scaled_top10.shape}")
print(f"  Samples: {X_training_scaled_top10.shape[0]:,}")
print(f"  Features: {X_training_scaled_top10.shape[1]}\n")

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 5: EVALUATE TREE ON ALL COHORTS
# ═══════════════════════════════════════════════════════════════════════════════════

print("="*90)
print("STEP 4: Tree Performance on All Cohorts (25 features)")
print("="*90 + "\n")

# Training set
y_pred_train_tree = tree_model.predict(X_training_scaled)
y_pred_proba_train_tree = tree_model.predict_proba(X_training_scaled)[:, 1]
tree_auc_train = roc_auc_score(y_training, y_pred_proba_train_tree)
tree_recall_train = recall_score(y_training, y_pred_train_tree)
tree_precision_train = precision_score(y_training, y_pred_train_tree)
tree_f1_train = f1_score(y_training, y_pred_train_tree)

print("Training Set (25 features):")
print(f"  AUC:       {tree_auc_train:.4f}")
print(f"  Recall:    {tree_recall_train:.4f}")
print(f"  Precision: {tree_precision_train:.4f}")
print(f"  F1-Score:  {tree_f1_train:.4f}\n")

# Internal test set
y_pred_test_tree = tree_model.predict(X_test_scaled)
y_pred_proba_test_tree = tree_model.predict_proba(X_test_scaled)[:, 1]
tree_auc_test = roc_auc_score(y_test, y_pred_proba_test_tree)
tree_recall_test = recall_score(y_test, y_pred_test_tree)
tree_precision_test = precision_score(y_test, y_pred_test_tree)
tree_f1_test = f1_score(y_test, y_pred_test_tree)

print("Internal Test Set (full 25 features):")
print(f"  AUC:       {tree_auc_test:.4f}")
print(f"  Recall:    {tree_recall_test:.4f}")
print(f"  Precision: {tree_precision_test:.4f}")
print(f"  F1-Score:  {tree_f1_test:.4f}\n")

# Pakistan hold-out
y_pred_pk_tree = tree_model.predict(X_pakistan_test_scaled)
y_pred_proba_pk_tree = tree_model.predict_proba(X_pakistan_test_scaled)[:, 1]
