print(f"  False Negatives:  {fn_pk:4d} (missed cancers) ← IMPORTANT")
print(f"  True Positives:   {tp_pk:4d} (correctly identified cancers)")
print()

# Calculate additional metrics
specificity_pk = tn_pk / (tn_pk + fp_pk) if (tn_pk + fp_pk) > 0 else 0
npv_pk = tn_pk / (tn_pk + fn_pk) if (tn_pk + fn_pk) > 0 else 0

print(f"Clinical Metrics (Pakistan Test Set):")
