print(f"  Positive Predictive Value (Precision): {pk_precision:.4f} = {tp_pk}/{tp_pk + fp_pk} = {pk_precision*100:.1f}% of predictions are correct")
print(f"  Negative Predictive Value: {npv_pk:.4f} = {tn_pk}/{tn_pk + fn_pk} = negative predictions are {npv_pk*100:.1f}% correct")
print()

