# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 1: Use Pakistan cohort for HITL study
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 1: Selecting HITL cohort from Pakistan validation set\n")

print("Rationale:")
print("  • Pakistan cohort shows better model performance")
print("  • Geographic diversity (unseen population)")
print("  • Clinically relevant for South Asian populations")
print("  • Size sufficient for 5-doctor consensus review")
print()

# Get predictions on Pakistan set
y_pred_proba_hitl = lr_model.predict_proba(X_pakistan_test_scaled)[:, 1]
y_pred_hitl = (y_pred_proba_hitl > 0.5).astype(int)

# Create risk scores
risk_scores = y_pred_proba_hitl

# Risk stratification
high_risk_mask = risk_scores > 0.7
moderate_risk_mask = (risk_scores >= 0.3) & (risk_scores <= 0.7)
low_risk_mask = risk_scores < 0.3

high_risk_count = high_risk_mask.sum()
moderate_risk_count = moderate_risk_mask.sum()
low_risk_count = low_risk_mask.sum()

print(f"Risk Distribution (Pakistan cohort n={len(risk_scores)}):")
print(f"  High Risk (>0.70):     {high_risk_count:5d} ({high_risk_count/len(risk_scores)*100:5.1f}%)")
print(f"  Moderate Risk (0.3-0.7): {moderate_risk_count:5d} ({moderate_risk_count/len(risk_scores)*100:5.1f}%)")
print(f"  Low Risk (<0.30):      {low_risk_count:5d} ({low_risk_count/len(risk_scores)*100:5.1f}%)")
print()

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 2: Stratified sampling for 500-case HITL cohort
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 2: Selecting 500-case HITL cohort with stratification\n")

# Target: 500 cases with proportional risk stratification
target_hitl = 500
prop_high = high_risk_count / len(risk_scores)
prop_moderate = moderate_risk_count / len(risk_scores)
prop_low = low_risk_count / len(risk_scores)

# Calculate samples per stratum
n_high = max(100, int(target_hitl * prop_high))  # At least 100 high-risk
n_moderate = max(150, int(target_hitl * prop_moderate))
n_low = target_hitl - n_high - n_moderate

# Stratified sampling
high_indices = np.where(high_risk_mask)[0]
moderate_indices = np.where(moderate_risk_mask)[0]
low_indices = np.where(low_risk_mask)[0]

# Randomly select from each stratum
np.random.seed(RANDOM_SEED)
hitl_high_indices = np.random.choice(high_indices, min(n_high, len(high_indices)), replace=False)
hitl_moderate_indices = np.random.choice(moderate_indices, min(n_moderate, len(moderate_indices)), replace=False)
hitl_low_indices = np.random.choice(low_indices, min(n_low, len(low_indices)), replace=False)

# Combine
hitl_indices = np.concatenate([hitl_high_indices, hitl_moderate_indices, hitl_low_indices])

print(f"Stratified HITL Cohort (n={len(hitl_indices)}):")
print(f"  High Risk cases:       {len(hitl_high_indices):3d}")
print(f"  Moderate Risk cases:   {len(hitl_moderate_indices):3d}")
print(f"  Low Risk cases:        {len(hitl_low_indices):3d}")
print(f"  Total:                 {len(hitl_indices):3d}")
print()

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 3: HITL Study Design
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 3: HITL Clinical Validation Study Design\n")

print(f"""
HITL STUDY DESIGN:

  Study Title: "Clinical Validation of SVSE Risk Stratification Model
                via Consensus Review by Multiple Expert Clinicians"

  Cohort: {len(hitl_indices)} patients from Pakistan validation set

  Expert Reviewers: 5 gastroenterologists/Colorectal Surgeons

  Review Process:
    1. Each clinician reviews case independently
    2. Reviews model prediction + clinical features
    3. Provides diagnosis: "Cancer (Advanced)" vs "No Cancer"
    4. Confidence score: 1-5 scale
    5. Consensus: ≥3/5 clinicians agree required

  Endpoints:
    Primary: Sensitivity, Specificity of model vs clinical consensus
    Secondary: Feature importance agreement with clinicians
    Exploratory: Disagreement patterns and reasons

  Statistical Analysis:
    • Cohen's kappa: Model vs consensus agreement
    • Sensitivity/Specificity with 95% CI
    • Subgroup analysis by risk stratum
""")

# ═══════════════════════════════════════════════════════════════════════════════════
# STEP 4: Create HITL Study Design CSV
# ═══════════════════════════════════════════════════════════════════════════════════

print("STEP 4: Creating HITL study design file\n")

# Prepare HITL cohort data
hitl_data = pd.DataFrame({
    'Case_ID': range(1, len(hitl_indices) + 1),
    'Patient_Index': hitl_indices,
    'Model_Prediction_Probability': y_pred_proba_hitl[hitl_indices],
    'Risk_Stratification': ['High' if y_pred_proba_hitl[idx] > 0.7
                            else 'Moderate' if y_pred_proba_hitl[idx] >= 0.3
                            else 'Low' for idx in hitl_indices],
    'Actual_Cancer_Status': y_pakistan_test.iloc[hitl_indices].values,
    'Clinician_1_Diagnosis': ['TBD'] * len(hitl_indices),
    'Clinician_2_Diagnosis': ['TBD'] * len(hitl_indices),
    'Clinician_3_Diagnosis': ['TBD'] * len(hitl_indices),
    'Clinician_4_Diagnosis': ['TBD'] * len(hitl_indices),
    'Clinician_5_Diagnosis': ['TBD'] * len(hitl_indices),
    'Consensus_Diagnosis': ['TBD'] * len(hitl_indices),
})

# Save to CSV
hitl_filename = f"{OUTPUT_DIR}/hitl_study_design.csv"
hitl_data.to_csv(hitl_filename, index=False)
print(f"✓ Saved: hitl_study_design.csv ({len(hitl_data)} cases)")
print()

