# STEP 5: Summary Statistics
# ═══════════════════════════════════════════════════════════════════════════════════

print("="*90)
print("HITL COHORT COMPOSITION")
print("="*90)
print()

print(f"Total cases: {len(hitl_data)}")
print()
print("Cases per risk level:")
print(f"  High Risk    ({'>0.70'}):  {(hitl_data['Risk_Stratification'] == 'High').sum():3d} ({(hitl_data['Risk_Stratification'] == 'High').sum()/len(hitl_data)*100:5.1f}%)")
print(f"  Moderate Risk (0.3-0.7): {(hitl_data['Risk_Stratification'] == 'Moderate').sum():3d} ({(hitl_data['Risk_Stratification'] == 'Moderate').sum()/len(hitl_data)*100:5.1f}%)")
print(f"  Low Risk     ('<0.30'):  {(hitl_data['Risk_Stratification'] == 'Low').sum():3d} ({(hitl_data['Risk_Stratification'] == 'Low').sum()/len(hitl_data)*100:5.1f}%)")
print()

